const idioma = /\/en(-[a-z]{2})?\//i.test(origen) || /^Contact (from|Form)/i.test(asunto) ? 'en'
  : /\/fr(-[a-z]{2})?\//i.test(origen) || /Contact du site/i.test(asunto) ? 'fr'
  : /\/de(-[a-z]{2})?\//i.test(origen) ? 'de' : 'es';
